INSERT INTO proof_points (proof_point_id, title, problem_text, action_text, outcome_text, attribution_note, register_note, client_or_category, status_label, featured_on_work_page, featured_in_resume_selected_work, image_url, sort_order)
VALUES ('rulebook-approach', 'The rulebook approach (the through line)', 'Most drift starts small. A chart computes its own version of a metric. The documentation describes last quarter''s schema. Two teams use the same word for different things. Nobody decides to let a system fall out of sync, it happens between decisions.', 'Works from a rulebook. The rules of a domain get written down once, in plain language the person who owns the business meaning can read, and the technical pieces are derived from that rather than maintained by hand.', 'It made him materially more productive. Previously the responsibility ended at design and project management, with development handed to someone else. Working this way, a project can be carried from concept through delivery by one person. That is the claim. Not that the method is novel.', 'His working method, not his invention. Described, never sold.', 'Describe, do not sell. Two or three sentences max, never a section. Never name transpilers, toolchains, or vendors. Safe line, use sparingly and never more than once per document: ''Consistency comes from derivation rather than discipline.''', NULL, NULL, FALSE, FALSE, NULL, 1) ON CONFLICT (proof_point_id) DO UPDATE SET title = EXCLUDED.title, problem_text = EXCLUDED.problem_text, action_text = EXCLUDED.action_text, outcome_text = EXCLUDED.outcome_text, attribution_note = EXCLUDED.attribution_note, register_note = EXCLUDED.register_note, client_or_category = EXCLUDED.client_or_category, status_label = EXCLUDED.status_label, featured_on_work_page = EXCLUDED.featured_on_work_page, featured_in_resume_selected_work = EXCLUDED.featured_in_resume_selected_work, image_url = EXCLUDED.image_url, sort_order = EXCLUDED.sort_order;

INSERT INTO proof_points (proof_point_id, title, problem_text, action_text, outcome_text, attribution_note, register_note, client_or_category, status_label, featured_on_work_page, featured_in_resume_selected_work, image_url, sort_order)
VALUES ('pm-portal', 'Product management platform, concept through production', 'A program serving more than 100 operating companies had no home. Content, coaching, assessment, and deliverables were scattered.', 'Designed and built the platform end to end: personas and access model, corporate SSO, frontend, API, PostgreSQL, content and artifact layer, and containerized infrastructure with automated deployment. Content and navigation are data rather than code, so the product and its specification cannot drift apart.', 'Live in production, serving PMs, operating partners, delivery coordinators, and program leads.', 'Sole responsibility, concept through production. Language to use: ''Designed and built end to end.''', 'The single strongest artifact in the record. Sole responsibility, concept to production.', 'Banyan Software', 'Live in production', TRUE, TRUE, NULL, 2) ON CONFLICT (proof_point_id) DO UPDATE SET title = EXCLUDED.title, problem_text = EXCLUDED.problem_text, action_text = EXCLUDED.action_text, outcome_text = EXCLUDED.outcome_text, attribution_note = EXCLUDED.attribution_note, register_note = EXCLUDED.register_note, client_or_category = EXCLUDED.client_or_category, status_label = EXCLUDED.status_label, featured_on_work_page = EXCLUDED.featured_on_work_page, featured_in_resume_selected_work = EXCLUDED.featured_in_resume_selected_work, image_url = EXCLUDED.image_url, sort_order = EXCLUDED.sort_order;

INSERT INTO proof_points (proof_point_id, title, problem_text, action_text, outcome_text, attribution_note, register_note, client_or_category, status_label, featured_on_work_page, featured_in_resume_selected_work, image_url, sort_order)
VALUES ('training-program-rebuild', 'Training curriculum rebuilt as an execution engagement', 'Inherited a module based program. Companies completed a course and went back to work unchanged.', 'Co-led the redesign with the program team: replaced the module sequence with a concept library surfaced at the point of need, removed hard gates in favor of facilitator judgment, capped CEO time at three to four hours.', 'Companies now finish with four artifacts they own, including a CEO signed strategy, a prioritized and capacity validated roadmap, a customer facing roadmap, and a ledger tracing every decision back to evidence.', 'Co-led with the program team. Language to use: ''Co-led the redesign.''', 'Line worth keeping: ''You don''t take the program and then go build your roadmap. You build your roadmap in the program.''', 'Banyan Software', 'Program redesign', FALSE, TRUE, NULL, 3) ON CONFLICT (proof_point_id) DO UPDATE SET title = EXCLUDED.title, problem_text = EXCLUDED.problem_text, action_text = EXCLUDED.action_text, outcome_text = EXCLUDED.outcome_text, attribution_note = EXCLUDED.attribution_note, register_note = EXCLUDED.register_note, client_or_category = EXCLUDED.client_or_category, status_label = EXCLUDED.status_label, featured_on_work_page = EXCLUDED.featured_on_work_page, featured_in_resume_selected_work = EXCLUDED.featured_in_resume_selected_work, image_url = EXCLUDED.image_url, sort_order = EXCLUDED.sort_order;

INSERT INTO proof_points (proof_point_id, title, problem_text, action_text, outcome_text, attribution_note, register_note, client_or_category, status_label, featured_on_work_page, featured_in_resume_selected_work, image_url, sort_order)
VALUES ('experience-layer-three-products', 'Experience layer across three executive reporting products', 'Three audiences needed three different questions answered from the same portfolio: workshop maturity, participation and performance; portfolio operations covering cloud spend, escrow and compliance; and technology due diligence covering deal management, time tracking and assignment. Portfolio Operations was also fed by generated exports, so the numbers described a moment already past.', 'Advised on and implemented the experience layer across all three, including interaction design, information architecture, and how the underlying data comes together. Rebuilt the Portfolio Operations dashboard onto a database backed foundation, replacing generated exports with live data and improving performance.', 'Three products, each built for its own audience and its own question, with Portfolio Operations now reporting current state rather than the last export.', 'Precisely: ''Advised on and implemented the experience layer.'' Not owned. Did not own the estate, the data platform, or the engineering. The Portfolio Operations rebuild onto live data is his outright. Do not say ''five reporting surfaces'' - there are three products.', 'The three products: PM Workshop (operating partners, program leads, participants), Portfolio Operations (finance and executive), Technical Due Diligence (corporate development and diligence teams).', 'Banyan Software', 'Three products', TRUE, TRUE, NULL, 4) ON CONFLICT (proof_point_id) DO UPDATE SET title = EXCLUDED.title, problem_text = EXCLUDED.problem_text, action_text = EXCLUDED.action_text, outcome_text = EXCLUDED.outcome_text, attribution_note = EXCLUDED.attribution_note, register_note = EXCLUDED.register_note, client_or_category = EXCLUDED.client_or_category, status_label = EXCLUDED.status_label, featured_on_work_page = EXCLUDED.featured_on_work_page, featured_in_resume_selected_work = EXCLUDED.featured_in_resume_selected_work, image_url = EXCLUDED.image_url, sort_order = EXCLUDED.sort_order;

INSERT INTO proof_points (proof_point_id, title, problem_text, action_text, outcome_text, attribution_note, register_note, client_or_category, status_label, featured_on_work_page, featured_in_resume_selected_work, image_url, sort_order)
VALUES ('diligence-project-brief', 'A project brief that aligned executives and surfaced a process breakdown', 'The diligence reporting product needed rebuilding, and there was no agreed statement of what was actually wrong with it or what the rebuild was for.', 'Wrote a project brief for executive review. It identified the opportunities, named the current gaps, and stated the problem without proposing a solution. Alignment on the brief is what leads to scoping, and scoping leads to a spec for execution.', 'An executive team aligned on the problem before anyone designed against it. The analysis behind the brief also surfaced a non-trivial breakdown in process: staging and production were serving two different dashboards.', NULL, 'The staging/production finding was a byproduct of doing the analysis properly, not a detective story. Overselling it turns a sound process into a boast. The value is the sequence: brief, alignment, scope, spec, execution.', 'Banyan Software', 'Problem brief', TRUE, TRUE, NULL, 5) ON CONFLICT (proof_point_id) DO UPDATE SET title = EXCLUDED.title, problem_text = EXCLUDED.problem_text, action_text = EXCLUDED.action_text, outcome_text = EXCLUDED.outcome_text, attribution_note = EXCLUDED.attribution_note, register_note = EXCLUDED.register_note, client_or_category = EXCLUDED.client_or_category, status_label = EXCLUDED.status_label, featured_on_work_page = EXCLUDED.featured_on_work_page, featured_in_resume_selected_work = EXCLUDED.featured_in_resume_selected_work, image_url = EXCLUDED.image_url, sort_order = EXCLUDED.sort_order;

INSERT INTO proof_points (proof_point_id, title, problem_text, action_text, outcome_text, attribution_note, register_note, client_or_category, status_label, featured_on_work_page, featured_in_resume_selected_work, image_url, sort_order)
VALUES ('ai-coach-scale', 'AI agents that scale one expert across a portfolio', 'Expert product coaching cannot sit inside a hundred companies at once. An AI coach can, but only if it teaches the same program the rest of the engagement runs on.', 'Advisory. Defined how the AI coach had to align to the program, what it was accountable for teaching, and how it fits the participant''s path through the portal. Set the boundary between what the coach handles and what the platform handles.', 'An on demand coach that reinforces the program instead of competing with it, reached through the portal at the point in the journey where the participant needs it.', 'Advisory only. The coach, skills toolkit, and maturity model were built by others. Contribution is program alignment and integration design. Must not imply authorship of the agents themselves.', 'Demonstrates knowing what an AI product is accountable for, and where it stops. That judgment is the scarce part.', NULL, NULL, FALSE, FALSE, NULL, 6) ON CONFLICT (proof_point_id) DO UPDATE SET title = EXCLUDED.title, problem_text = EXCLUDED.problem_text, action_text = EXCLUDED.action_text, outcome_text = EXCLUDED.outcome_text, attribution_note = EXCLUDED.attribution_note, register_note = EXCLUDED.register_note, client_or_category = EXCLUDED.client_or_category, status_label = EXCLUDED.status_label, featured_on_work_page = EXCLUDED.featured_on_work_page, featured_in_resume_selected_work = EXCLUDED.featured_in_resume_selected_work, image_url = EXCLUDED.image_url, sort_order = EXCLUDED.sort_order;

INSERT INTO proof_points (proof_point_id, title, problem_text, action_text, outcome_text, attribution_note, register_note, client_or_category, status_label, featured_on_work_page, featured_in_resume_selected_work, image_url, sort_order)
VALUES ('agents-in-strategy-work', 'Agents used to sharpen strategy before execution', 'Strategy work is limited by how much context one person can absorb and how much evidence they can assemble before a decision has to be made, which usually produces a position argued from partial information or alignment attempted after execution has already started.', 'Uses agents as a tool inside the engagement to research the context, pressure test a position, and assemble evidence, so problems and opportunities are identified accurately and alignment is built before execution starts. Worked example: for an FDA cleared medical technology company focused on breast cancer prevention, built an agent that acted as domain expert across the engagement, supporting strategic pilot program design at multi-tiered facilities, distribution opportunity identification, and early flagging of insurance carrier friction.', 'Better problem identification, opportunities surfaced that would not have come up otherwise, and concrete evidence in front of stakeholders early enough for alignment to be cheap.', NULL, 'Emphasis is on how agents are used, not on the fact that he builds them. Do not lead with the tooling. The claim is that the strategy work is better, not that there are more agents.', 'Medical technology', 'Strategy', FALSE, TRUE, NULL, 7) ON CONFLICT (proof_point_id) DO UPDATE SET title = EXCLUDED.title, problem_text = EXCLUDED.problem_text, action_text = EXCLUDED.action_text, outcome_text = EXCLUDED.outcome_text, attribution_note = EXCLUDED.attribution_note, register_note = EXCLUDED.register_note, client_or_category = EXCLUDED.client_or_category, status_label = EXCLUDED.status_label, featured_on_work_page = EXCLUDED.featured_on_work_page, featured_in_resume_selected_work = EXCLUDED.featured_in_resume_selected_work, image_url = EXCLUDED.image_url, sort_order = EXCLUDED.sort_order;

INSERT INTO proof_points (proof_point_id, title, problem_text, action_text, outcome_text, attribution_note, register_note, client_or_category, status_label, featured_on_work_page, featured_in_resume_selected_work, image_url, sort_order)
VALUES ('startup-work', 'Startup work, concept to capital', 'Two early companies with real technology and no product story an outsider could buy.', 'For an FDA cleared medical technology company focused on breast cancer prevention, led a pivot from a multi state Series A to a focused single state validation program and built the seed investor materials, shifting the narrative from detection to prevention. For an AI driven materials discovery company, translated lab technology into a customer facing platform through facilitation and interactive prototyping.', 'Investor ready materials and a defined MVP path in both cases. Phase one delivered on the medical device engagement, with the strategy and investment direction in place.', 'Neither client is named. Describe both by category. The medical technology engagement concluded after phase one due to internal changes on the client side.', 'Covered on the resume via the m+d2 & Associates and Vortent Partners job entries rather than as a standalone Work page item.', NULL, NULL, FALSE, FALSE, NULL, 8) ON CONFLICT (proof_point_id) DO UPDATE SET title = EXCLUDED.title, problem_text = EXCLUDED.problem_text, action_text = EXCLUDED.action_text, outcome_text = EXCLUDED.outcome_text, attribution_note = EXCLUDED.attribution_note, register_note = EXCLUDED.register_note, client_or_category = EXCLUDED.client_or_category, status_label = EXCLUDED.status_label, featured_on_work_page = EXCLUDED.featured_on_work_page, featured_in_resume_selected_work = EXCLUDED.featured_in_resume_selected_work, image_url = EXCLUDED.image_url, sort_order = EXCLUDED.sort_order;

