VALUES ('banyan-software', 'Banyan Software', 'Technical Advisor, Product Strategy and UX', '2026-02-01', NULL, TRUE, 'banyan', 'Portfolio of 100+ B2B SaaS operating companies. Supports operating company teams, product management, and technology due diligence. Platform, reporting products, and workshop work described above.', 'Designed and built the product management platform serving the portfolio, concept through production: access model, frontend, API, PostgreSQL, content layer, and deployed infrastructure.
Advised on and implemented the experience layer across three executive reporting products: PM Workshop covering operating company maturity, participation and performance; Portfolio Operations covering cloud spend, escrow and compliance; and Technical Due Diligence covering deal management, time tracking and assignment.
Rebuilt the Portfolio Operations dashboard onto a database backed foundation, replacing generated exports with live data and improving performance.
Co-led the redesign of the AI PM Workshop from training curriculum to execution engagement, with four owned artifacts as the outcome.
Wrote the project brief for the diligence reporting rebuild, aligning the executive team on the problem before scoping. The supporting analysis surfaced a process breakdown where staging and production served two different dashboards.', NULL, TRUE, TRUE, FALSE, 1) ON CONFLICT (job_entry_id) DO UPDATE SET company = EXCLUDED.company, job_title = EXCLUDED.job_title, start_date = EXCLUDED.start_date, end_date = EXCLUDED.end_date, is_current = EXCLUDED.is_current, display_group_key = EXCLUDED.display_group_key, summary_text_variant_a = EXCLUDED.summary_text_variant_a, summary_text_variant_b = EXCLUDED.summary_text_variant_b, compressed_line = EXCLUDED.compressed_line, include_in_variant_a = EXCLUDED.include_in_variant_a, include_in_variant_b = EXCLUDED.include_in_variant_b, is_pre2019 = EXCLUDED.is_pre2019, sort_order = EXCLUDED.sort_order;

