-- ----------------------------------------------------------------------------
-- ResumeVariants: Table: ResumeVariants. Two variants, one spine, per David_Shadle_Resume_Variants_v1.md. Variant A is public/served from the site; Variant B is sent directly and never published.
-- ----------------------------------------------------------------------------
INSERT INTO resume_variants (resume_variant_id, label, audience_description, summary_text, published_on_site)
VALUES ('variant-a', 'Variant A — Consulting and Advisory', 'Public. Linked from davidshadle.com, offered as a PDF download. Target length: two pages.', 'I build the systems that turn strategy into working software. Most advisors stop at the recommendation. I keep going, through the model, the interface, and the handoff, so the thing that gets agreed on is the thing that gets shipped.

I start with the problem and write it down before anyone proposes a solution. From there I work from a rulebook: the rules of a domain written down once in plain language, with the technical pieces derived from that rather than maintained by hand. It is what lets me deliver complete projects rather than stopping at design and project management.

Twenty five years in product strategy and design make the systems worth building. Full stack product practitioner. Not just capable of wearing several hats at once, but confident delivering the outcome in each.', TRUE) ON CONFLICT (resume_variant_id) DO UPDATE SET label = EXCLUDED.label, audience_description = EXCLUDED.audience_description, summary_text = EXCLUDED.summary_text, published_on_site = EXCLUDED.published_on_site;

INSERT INTO resume_variants (resume_variant_id, label, audience_description, summary_text, published_on_site)
VALUES ('variant-b', 'Variant B — Principal and Director Roles', 'Sent directly for specific roles. Never published online. Conventional reverse-chronological structure for applicant tracking systems and hiring managers.', 'Product strategy and design leader with twenty five years across enterprise platforms, cloud infrastructure, and early stage companies, including principal roles at Microsoft and Oracle. I define what to build and why, align the people who have to agree, and stay with the work through delivery.

I also build. Over the last two years I have designed and shipped a production platform end to end and implemented the experience layer across three executive reporting products. Working from a written rulebook rather than hand-maintained specs is what extended me from design and project management into complete delivery. That range means no handoff gap between strategy, design, and engineering.

Looking for defined ownership at a small to mid sized organization.', FALSE) ON CONFLICT (resume_variant_id) DO UPDATE SET label = EXCLUDED.label, audience_description = EXCLUDED.audience_description, summary_text = EXCLUDED.summary_text, published_on_site = EXCLUDED.published_on_site;

