-- ----------------------------------------------------------------------------
-- LandingPages: Table: LandingPages. One promotional landing page per row, reachable only by its direct URL. LandingPageId is the URL slug.
-- ----------------------------------------------------------------------------
INSERT INTO landing_pages (landing_page_id, meta_title, meta_description, eyebrow, headline, lede, video_url, primary_cta_label, primary_cta_href, secondary_cta_label, secondary_cta_href, is_published)
VALUES ('idea-to-evidence', 'Idea to Evidence: David Shadle', 'One product idea, carried to a working prototype your customers have tested, so you decide what to build on evidence. A service for Banyan operating companies.', 'Idea to Evidence', 'New interaction concepts, prototyped and tested with your customers.', 'Idea to Evidence takes one idea for how your product could work and carries it to a working prototype that your customers (or agents) can interact with. You leave with evidence and a decision, not a recommendation.', 'https://www.youtube.com/watch?v=49NfG8CoGJQ', 'Let''s get started', 'mailto:david@davidshadle.com?subject=Idea%20to%20Evidence%3A%20Discovery%20conversation', 'Download the capability statement (PDF)', '/downloads/David-Shadle-Idea-to-Evidence-Capability-Statement.pdf', FALSE) ON CONFLICT (landing_page_id) DO UPDATE SET meta_title = EXCLUDED.meta_title, meta_description = EXCLUDED.meta_description, eyebrow = EXCLUDED.eyebrow, headline = EXCLUDED.headline, lede = EXCLUDED.lede, video_url = EXCLUDED.video_url, primary_cta_label = EXCLUDED.primary_cta_label, primary_cta_href = EXCLUDED.primary_cta_href, secondary_cta_label = EXCLUDED.secondary_cta_label, secondary_cta_href = EXCLUDED.secondary_cta_href, is_published = EXCLUDED.is_published;

INSERT INTO landing_pages (landing_page_id, meta_title, meta_description, eyebrow, headline, lede, video_url, primary_cta_label, primary_cta_href, secondary_cta_label, secondary_cta_href, is_published)
VALUES ('designing-for-people-and-agents', 'Designing for People and Agents: Guild Sessions by David Shadle', 'Five 40-minute Guild Sessions for Banyan operating companies on how AI agents change forms, reports, help, and the service behind the screen. Each one leaves you something to try the following week.', 'Guild Sessions', 'Designing for People and Agents', 'Software was built for a person at a screen. More and more, the user is an agent acting for that person, with no screen at all, and most analytics cannot see it. Five 40-minute Guild Sessions, each on one place the shift shows up in a product.', NULL, 'Ask about the next session', 'mailto:david@davidshadle.com?subject=Guild%20Sessions%3A%20Designing%20for%20People%20and%20Agents', 'See the five sessions', '#the-five-sessions', FALSE) ON CONFLICT (landing_page_id) DO UPDATE SET meta_title = EXCLUDED.meta_title, meta_description = EXCLUDED.meta_description, eyebrow = EXCLUDED.eyebrow, headline = EXCLUDED.headline, lede = EXCLUDED.lede, video_url = EXCLUDED.video_url, primary_cta_label = EXCLUDED.primary_cta_label, primary_cta_href = EXCLUDED.primary_cta_href, secondary_cta_label = EXCLUDED.secondary_cta_label, secondary_cta_href = EXCLUDED.secondary_cta_href, is_published = EXCLUDED.is_published;

-- ----------------------------------------------------------------------------
-- LandingPageSections: Table: LandingPageSections. The ordered sections of a landing page. Kind selects the renderer.
-- ----------------------------------------------------------------------------
INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('idea-to-evidence-why-now', 'idea-to-evidence', 1, 'prose', NULL, 'Why now', 'AI can now do part of the work your customers do by hand.', 'AI can act on a customer''s behalf, anticipate a need, and complete a task. Forms, reports, help, and transactions can all work differently. That opens new ways for your product to serve customers, and gives them a reason to renew and buy more.

Most leadership teams already have ideas about where to start. What is hard to find is the time to learn which idea is worth building before committing to build it. This engagement is built to find that out, in a few focused sessions, with the building and testing done outside your leadership team''s calendar.', NULL, NULL) ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('idea-to-evidence-what-you-get', 'idea-to-evidence', 2, 'list', NULL, 'What you get', 'Five things you take away.', NULL, NULL, NULL) ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('idea-to-evidence-ways-to-engage', 'idea-to-evidence', 3, 'cards', 'ways-to-engage', 'Ways to engage', 'Choose how far to go.', 'The level is chosen in Discovery and can be extended later.', NULL, NULL) ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('idea-to-evidence-commitments', 'idea-to-evidence', 4, 'list', NULL, 'Commitments', 'Five commitments.', NULL, NULL, NULL) ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('idea-to-evidence-who-it-is-for', 'idea-to-evidence', 5, 'prose', NULL, 'Who it is for', 'Operating company leadership.', 'Leadership of a Banyan operating company, usually the CEO or the person who holds product direction, working with the Operating Partner who owns the Value Creation Plan. OpCos arrive by referral from an Operating Partner or Banyan leadership, or after a Guild Session on an interaction pattern. Both routes begin with a free Discovery conversation.', NULL, NULL) ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('idea-to-evidence-what-we-ask', 'idea-to-evidence', 6, 'list', NULL, 'What we ask of you', 'What the engagement needs from your side.', NULL, NULL, NULL) ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('idea-to-evidence-your-data', 'idea-to-evidence', 7, 'prose', NULL, 'Your data', 'Your data stays yours.', 'Your data is used only for your engagement. Testing participants give consent and are not named. Everything produced, including testing records, transfers to you, and the provider keeps no copy. Nothing is shared with another company.', NULL, NULL) ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('idea-to-evidence-about', 'idea-to-evidence', 8, 'prose', NULL, 'About', 'David Shadle.', 'Twenty years leading product, design, and engineering teams. I work where experience design and product strategy meet, and I build what I design. AI tools do the volume work of research, drafting, and building. My judgment decides what matters.', NULL, NULL) ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('idea-to-evidence-to-start', 'idea-to-evidence', 9, 'callout', 'to-start', 'To start', 'Request a free Discovery conversation.', 'One conversation to confirm fit, name the metric, and agree where to start.', NULL, NULL) ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('designing-for-people-and-agents-the-series', 'designing-for-people-and-agents', 1, 'prose', NULL, 'The series', 'One shift, five places it shows up.', 'Designing for People and Agents is a series of five 40-minute Guild Sessions, held monthly, live and online, presented by David Shadle. Each one covers one place the shift shows up in a product. Every session leaves attendees with something to try the following week.

The sessions build on one another. The series starts with seeing who uses the product, moves through what the product exposes and what its terms mean, and ends with how the service runs and how people interact with it. Each session also stands on its own.

Any role at an OpCo can attend: leadership, product, engineering, design, and customer-facing teams. Technical topics stay at a high level, leaning technical where they apply to the business and the reasons to integrate.', NULL, NULL) ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('designing-for-people-and-agents-why-now', 'designing-for-people-and-agents', 2, 'prose', NULL, 'Why now', 'The shift is already in the traffic.', 'Fastly reported in June 2026 that AI traffic grew about 6.5 times faster than human traffic in the first five months of the year. Cloudflare reported in July 2026 that more than half of internet traffic is now non-human. DataDome counted 17.7 billion AI agent requests in a single quarter, up 45 percent on the quarter before.

Some of that traffic collects content and sends nothing back. Some of it is an agent acting for a real customer: checking availability, comparing options, completing a task. Most products were not designed for that customer, and most measurement does not count it. Forms, reports, and help, the patterns that shaped business software, are changing at the same time.

Much of what OpCos need to respond is not new. The principles behind it have been in use for decades. What is new is how much they now matter, and how quickly. The series connects the two.', NULL, NULL) ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('designing-for-people-and-agents-the-five-sessions', 'designing-for-people-and-agents', 3, 'cards', 'the-five-sessions', 'The five sessions', 'One session a month.', 'After each session, attendees receive a one-page takeaway with the self-check and the action to try.', NULL, NULL) ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('designing-for-people-and-agents-after-the-session', 'designing-for-people-and-agents', 4, 'cards', NULL, 'After the session', 'Two ways to use what you learn.', NULL, 'How an Idea to Evidence engagement works', '/idea-to-evidence') ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('designing-for-people-and-agents-who-presents', 'designing-for-people-and-agents', 5, 'prose', NULL, 'Who presents', 'David Shadle.', 'Content for every session is written and presented by David Shadle, who has spent twenty years leading product, design, and engineering teams. Examples drawn from the portfolio are named only with the OpCo''s agreement. The series informs. It does not assess any OpCo, roadmap, or team.', NULL, NULL) ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

INSERT INTO landing_page_sections (landing_page_section_id, landing_page, sort_order, kind, anchor_id, eyebrow, heading, body_text, link_label, link_href)
VALUES ('designing-for-people-and-agents-next-session', 'designing-for-people-and-agents', 6, 'callout', NULL, 'Next session', 'Ask about the next session.', 'Dates will be announced to Banyan operating companies. To be told first, or to ask about bringing a pattern into your own product, get in touch.', NULL, NULL) ON CONFLICT (landing_page_section_id) DO UPDATE SET landing_page = EXCLUDED.landing_page, sort_order = EXCLUDED.sort_order, kind = EXCLUDED.kind, anchor_id = EXCLUDED.anchor_id, eyebrow = EXCLUDED.eyebrow, heading = EXCLUDED.heading, body_text = EXCLUDED.body_text, link_label = EXCLUDED.link_label, link_href = EXCLUDED.link_href;

