VALUES ('designing-for-people-and-agents-the-five-sessions-the-user-you-cannot-see-fact-2', 'designing-for-people-and-agents-the-five-sessions-the-user-you-cannot-see', 2, 'Try it on your own', 'Pull 30 days of logs. Separate browser traffic, your own clients, and everything else. Rebuild one agent session in order and note where it stopped.') ON CONFLICT (landing_page_item_fact_id) DO UPDATE SET landing_page_item = EXCLUDED.landing_page_item, sort_order = EXCLUDED.sort_order, label = EXCLUDED.label, body_text = EXCLUDED.body_text;

