VALUES ('designing-for-people-and-agents-the-five-sessions-the-user-you-cannot-see-fact-4', 'designing-for-people-and-agents-the-five-sessions-the-user-you-cannot-see', 4, 'Reports against', 'Gross and net retention, where agents act for existing customers.') ON CONFLICT (landing_page_item_fact_id) DO UPDATE SET landing_page_item = EXCLUDED.landing_page_item, sort_order = EXCLUDED.sort_order, label = EXCLUDED.label, body_text = EXCLUDED.body_text;

